#include "PresetManager.h"
namespace cymbalforge { bool PresetManager::save(const juce::File& f,const CymbalParameters& p) { auto o=new juce::DynamicObject; o->setProperty("velocity",p.velocity.load()); o->setProperty("position",p.position.load()); o->setProperty("brightness",p.brightness.load()); o->setProperty("decay",p.decay.load()); o->setProperty("noise",p.noise.load()); o->setProperty("reverb",p.reverb.load()); o->setProperty("gain",p.gain.load()); o->setProperty("modes",p.modes.load()); return f.replaceWithText(juce::JSON::toString(juce::var(o),true)); } bool PresetManager::load(const juce::File& f,CymbalParameters& p) { auto v=juce::JSON::parse(f); if(!v.isObject()) return false; auto* o=v.getDynamicObject(); p.velocity=o->getProperty("velocity"); p.position=o->getProperty("position"); p.brightness=o->getProperty("brightness"); p.decay=o->getProperty("decay"); p.noise=o->getProperty("noise"); p.reverb=o->getProperty("reverb"); p.gain=o->getProperty("gain"); p.modes=int(o->getProperty("modes")); return true; } }
